-- Reviewed Damascus menu import; no billing, offers, loyalty or customer mutations
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE damascus_before ON COMMIT DROP AS SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) snapshot;
DO $identity$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' AND slug='brand-067febfb04db' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Damascus brand identity changed';END IF;END $identity$;
CREATE TEMP TABLE damascus_expected_categories ON COMMIT DROP AS SELECT * FROM public.menu_categories WITH NO DATA;
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9') AND (EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM damascus_expected_categories) OR EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM damascus_expected_categories EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9')) THEN RAISE EXCEPTION 'Existing categories differ; preserve owner changes';END IF;END $catalog$;
CREATE TEMP TABLE damascus_expected_products ON COMMIT DROP AS SELECT * FROM public.menu_products WITH NO DATA;
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9') AND (EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM damascus_expected_products) OR EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM damascus_expected_products EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9')) THEN RAISE EXCEPTION 'Existing products differ; preserve owner changes';END IF;END $catalog$;
DO $logo$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9') THEN RAISE EXCEPTION 'Damascus settings missing';END IF;IF EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' AND ((logo_storage_path IS NOT NULL AND logo_storage_path IS DISTINCT FROM 'c6c0390a-04ad-46b8-a43d-82e1b7e579b9/identity/damascus-20261104-ac3320de7ce6825b.webp') OR logo_url IS NOT NULL)) OR EXISTS(SELECT 1 FROM public.cafe_custom_identity WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' AND (logo_storage_path IS DISTINCT FROM 'c6c0390a-04ad-46b8-a43d-82e1b7e579b9/identity/damascus-20261104-ac3320de7ce6825b.webp' OR logo_url IS NOT NULL OR palette IS DISTINCT FROM '{"primary":"#211B17","secondary":"#F4E7CF","accent":"#D9B66F","background":"#FAF5EA","text":"#29221C","button":"#A51F2D"}'::jsonb)) THEN RAISE EXCEPTION 'Existing Damascus identity differs; preserve owner changes';END IF;END $logo$;
UPDATE public.cafe_settings SET logo_storage_path='c6c0390a-04ad-46b8-a43d-82e1b7e579b9/identity/damascus-20261104-ac3320de7ce6825b.webp',updated_at=now() WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' AND logo_storage_path IS DISTINCT FROM 'c6c0390a-04ad-46b8-a43d-82e1b7e579b9/identity/damascus-20261104-ac3320de7ce6825b.webp';
DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'c6c0390a-04ad-46b8-a43d-82e1b7e579b9'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) INTO actual;IF actual IS DISTINCT FROM(SELECT snapshot FROM damascus_before) THEN RAISE EXCEPTION 'Protected brands, loyalty, billing or customer data changed';END IF;IF(SELECT count(*) FROM public.menu_products WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9' AND available AND price>0)<>110 OR(SELECT count(*) FROM public.menu_categories WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9')<>9 OR(SELECT sum(coalesce(jsonb_array_length(commerce_details->'options'),0)) FROM public.menu_products WHERE cafe_id='c6c0390a-04ad-46b8-a43d-82e1b7e579b9')<>0 THEN RAISE EXCEPTION 'Damascus count, prices or media mismatch';END IF;END $verify$;
COMMIT;
